  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color transparency helper logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Grid proportions matching the 9:16 aspect ratio beautifully
  const gridWidth = Math.min(width * 0.86, 900);
  const gridHeight = gridWidth * 1.15;
  const gridLeft = (width - gridWidth) / 2;
